1	#!/usr/bin/env python3
2	"""OpenSurvey HTTP service."""
3	import argparse
4	import json
5	import re
6	from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
7	from pathlib import Path
8	import signal
9	import sqlite3
10	import threading
11	from urllib.parse import urlsplit
12	
13	PRODUCT = "OpenSurvey"
14	RESOURCE = "surveys"
15	MAX_BODY_BYTES = 10 * 1024 * 1024
16	QUESTION_TYPES = ("text", "single_choice")
17	
18	PAGE = r"""<!doctype html>
19	<html lang="zh-CN">
20	<meta charset="utf-8">
21	<meta name="viewport" content="width=device-width,initial-scale=1">
22	<title>OpenSurvey · 问卷调查与反馈管理</title>
23	<style>
24	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
25	*{box-sizing:border-box}
26	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
27	a{color:var(--blue)}
28	h1{margin-bottom:.2rem}
29	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
30	.muted{color:var(--grey);font-size:.92rem}
31	ul.plain{list-style:none;padding-left:0}
32	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
33	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
34	input[type=text],textarea{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
35	textarea{resize:vertical}
36	/* 标题与选项允许内部换行：用随内容增高的 textarea 展示，不能压成单行输入框 */
37	textarea.grow{resize:none;overflow:hidden;min-height:2.4rem;line-height:1.5}
38	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
39	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
40	.q-index{font-weight:700}
41	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
42	.tag.required{background:#fdecea;color:var(--red)}
43	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
44	.spacer{flex:1}
45	button{font:inherit;cursor:pointer}
46	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
47	.btn.secondary{background:#fff;color:var(--blue)}
48	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
49	.link.danger{color:var(--red)}
50	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
51	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
52	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
53	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
54	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
55	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
56	/* 保存状态条：与错误提示条区分开，明确“刚才那次提交已保存”与“还有未保存修改” */
57	.save-status{margin:1rem 0;display:flex;flex-direction:column;gap:.5rem}
58	.save-status[hidden]{display:none}
59	.save-note{border-radius:.5rem;padding:.7rem 1rem;white-space:normal}
60	.save-note.saved{border:1px solid #1e7e45;background:#ecf7f0;color:#155c33}
61	.save-note.dirty{border:1px solid #9a6d12;background:#fdf6e3;color:#7a5207}
62	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
63	.invalid{border-color:var(--red)!important;background:#fdf6f5}
64	.detail-meta{color:var(--grey);font-size:.9rem}
65	.detail-desc,.opt-text-display{white-space:pre-wrap}
66	/* 标题中被接口保留的内部换行在列表与详情中也要原样显示 */
67	h2,.q-list .q-line,ul.plain a{white-space:pre-wrap}
68	.q-list>li{margin:1rem 0}
69	.q-list .q-line{font-weight:600}
70	.q-list ol{margin:.4rem 0 0 1.4rem}
71	</style>
72	<main>
73	<h1>OpenSurvey</h1>
74	<p>问卷调查与反馈管理</p>
75	<div id="app"></div>
76	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
77	</main>
78	<script>
79	"use strict";
80	const app = document.getElementById("app");
81	
82	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
83	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
84	// 返回也必须丢弃，不能覆盖用户当前所在页面。
85	let activeView = 0;
86	
87	function h(tag, attrs, ...children) {
88	  const el = document.createElement(tag);
89	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
90	    if (v === null || v === undefined) continue;
91	    if (k === "class") el.className = v;
92	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
93	    else el.setAttribute(k, v);
94	  }
95	  for (const child of children.flat()) {
96	    if (child === null || child === undefined) continue;
97	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
98	  }
99	  return el;
100	}
101	
102	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
103	
104	function buildSurveyForm(existing, hooks, view) {
105	  const mode = existing ? "edit" : "create";
106	
107	  const banner = h("div", {class: "banner", id: "form-banner"});
108	  banner.hidden = true;
109	
110	  // 编辑模式下保存结果的状态条：成功保存与“仍有未保存修改”必须分开展示，
111	  // 不能只给一条笼统的“保存成功”。新建模式不使用它（保存成功即进入详情）。
112	  const statusBar = h("div", {class: "save-status", id: "save-status", role: "status"});
113	  statusBar.hidden = true;
114	
115	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
116	    maxlength: "200", placeholder: "请输入问卷标题（可含换行）"});
117	  const titleErr = h("p", {class: "field-err", id: "title-err"});
118	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
119	  const qBox = h("div", {id: "questions"});
120	  const qErr = h("p", {class: "field-err", id: "questions-err"});
121	
122	  function renumber() {
123	    const cards = qBox.querySelectorAll(".q-card");
124	    cards.forEach((card, i) => {
125	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
126	      card.querySelectorAll(".opt-row").forEach((row, j) => {
127	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
128	      });
129	    });
130	  }
131	
132	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
133	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
134	  function autoGrow(el) {
135	    el.style.height = "auto";
136	    el.style.height = `${el.scrollHeight}px`;
137	  }
138	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
139	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
140	
141	  function optionRow(value) {
142	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
143	    text.addEventListener("input", () => autoGrow(text));
144	    if (value !== undefined && value !== null) { text.value = value; scheduleGrow(text); }
145	    const row = h("div", {class: "opt-row"},
146	      h("span", {class: "opt-index"}, "选项"),
147	      text,
148	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
149	    );
150	    return row;
151	  }
152	
153	  function addQuestion(type, prefill) {
154	    const isChoice = type === "single_choice";
155	    const options = h("div", {class: "options"});
156	    const card = h("div", {class: "card q-card", "data-type": type},
157	      h("div", {class: "q-head"},
158	        h("span", {class: "q-index"}, "第 N 题"),
159	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
160	        h("label", {class: "req"},
161	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
162	        h("span", {class: "spacer"}),
163	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
164	      ),
165	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
166	      h("p", {class: "field-err q-title-err"})
167	    );
168	    if (isChoice) {
169	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
170	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
171	      else options.append(optionRow(), optionRow());
172	      card.append(
173	        options,
174	        h("p", {class: "field-err opt-err"}),
175	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
176	      );
177	      card.querySelector(".add-opt").addEventListener("click", () => {
178	        options.append(optionRow());
179	        renumber();
180	        options.querySelector(".opt-row:last-child .opt-text").focus();
181	      });
182	    }
183	    const qTitleEl = card.querySelector(".q-title");
184	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
185	    if (prefill) {
186	      qTitleEl.value = prefill.title != null ? prefill.title : "";
187	      card.querySelector(".q-required").checked = !!prefill.required;
188	    }
189	    scheduleGrow(qTitleEl);
190	    qBox.append(card);
191	    renumber();
192	    if (!prefill) qTitleEl.focus();
193	    return card;
194	  }
195	
196	  function clearErrors() {
197	    banner.hidden = true;
198	    banner.replaceChildren();
199	    titleErr.textContent = "";
200	    qErr.textContent = "";
201	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
202	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
203	  }
204	
205	  function hideSaveStatus() {
206	    statusBar.hidden = true;
207	    statusBar.replaceChildren();
208	  }
209	
210	  // 保存成功后：绿色块只陈述“刚才提交的内容已保存”；若等待期间又有修改，
211	  // 再追加一块黄色“当前还有未保存的修改”。两者同时出现、含义互不混淆。
212	  function renderSaveStatus(dirty) {
213	    statusBar.replaceChildren(
214	      h("div", {class: "save-note saved", id: "save-note-saved"},
215	        h("strong", null, "已保存：刚才提交的内容已保存到服务器。")),
216	      dirty
217	        ? h("div", {class: "save-note dirty", id: "save-note-dirty"},
218	            h("strong", null,
219	              "当前还有未保存的修改：页面内容在点击保存后又被改动（等待结果期间的修改不会自动补交）。可继续编辑，并再次点击“保存修改”。"))
220	        : null
221	    );
222	    statusBar.hidden = false;
223	  }
224	
225	  // 按与提交时完全相同的规则读取当前表单：标题/题目标题/选项去掉首尾空白，
226	  // 说明与内部换行原样保留。返回结构可直接做整体相等比较，用来判断“点击保存
227	  // 之后表单是否又被改过”。改过又恢复原值时结构相同，不会被当成有未保存修改。
228	  function currentState() {
229	    return {
230	      title: titleInput.value.trim(),
231	      description: descArea.value,
232	      questions: [...qBox.querySelectorAll(".q-card")].map(card => ({
233	        type: card.dataset.type,
234	        title: card.querySelector(".q-title").value.trim(),
235	        required: card.querySelector(".q-required").checked,
236	        options: [...card.querySelectorAll(".opt-text")].map(el => el.value.trim())
237	      }))
238	    };
239	  }
240	
241	  function sameState(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
242	
243	  function showBanner(items) {
244	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
245	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
246	    banner.hidden = false;
247	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
248	  }
249	
250	  const actionButtons = [
251	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
252	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
253	    h("span", {class: "spacer"})
254	  ];
255	  if (mode === "edit") {
256	    // 离开编辑页即丢弃全部未保存的增删与输入
257	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
258	  }
259	  actionButtons.push(h("button", {type: "submit", class: "btn"},
260	    mode === "edit" ? "保存修改" : "保存整份问卷"));
261	
262	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
263	    banner,
264	    statusBar,
265	    h("section", null,
266	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
267	      mode === "edit"
268	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
269	        : null,
270	      h("label", {for: "survey-title"}, "标题"),
271	      titleInput, titleErr,
272	      h("label", {for: "survey-desc"}, "说明"),
273	      descArea,
274	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
275	      qBox, qErr,
276	      h("div", {class: "row-actions"}, actionButtons)
277	    )
278	  );
279	
280	  titleInput.addEventListener("input", () => autoGrow(titleInput));
281	  if (mode === "edit") {
282	    titleInput.value = existing.title != null ? existing.title : "";
283	    descArea.value = existing.description || "";
284	    existing.questions.forEach(question => addQuestion(question.type, question));
285	    renumber();
286	    scheduleGrow(titleInput);
287	
288	    // 最近一次服务器确认保存的表单内容（点击保存时的快照）。它只用于成功返回
289	    // 后判断当前表单相对那次提交有没有新改动；等待期间的输入始终留在表单里，
290	    // 不会被它覆盖，也不会被自动补交。
291	    let savedState = currentState();
292	
293	    function refreshDirty() {
294	      const dirtyNote = statusBar.querySelector("#save-note-dirty");
295	      // 尚未成功保存过（状态条隐藏）时无需提示。
296	      if (statusBar.hidden || !dirtyNote) return;
297	      // 与点击保存时的整份内容比较：改过又恢复原值即视为无未保存修改。
298	      dirtyNote.hidden = sameState(currentState(), savedState);
299	    }
300	
301	    // 监听编辑页上全部真实编辑动作（标题/说明/题目标题/选项输入、必填勾选、
302	    // 题目与选项增删）。题目卡片是动态增删的，因此在表单上做事件委托。
303	    form.addEventListener("input", refreshDirty);
304	    form.addEventListener("change", event => {
305	      if (event.target.closest && event.target.closest(".q-required")) refreshDirty();
306	    });
307	    form.addEventListener("click", event => {
308	      const actionable = event.target.closest
309	        && event.target.closest("button.add-opt, button.link.danger, button.btn.secondary");
310	      if (actionable) {
311	        // 新增/删除在本次点击处理中完成，延到冒泡后再读取最终 DOM。
312	        queueMicrotask(refreshDirty);
313	      }
314	    });
315	
316	    hooks = hooks || {};
317	    hooks.markSaved = state => { savedState = state; };
318	    hooks.isCurrent = state => sameState(currentState(), state);
319	  }
320	
321	  async function submitForm(event) {
322	    event.preventDefault();
323	    clearErrors();
324	    hideSaveStatus();
325	    const problems = [];
326	
327	    const title = titleInput.value.trim();
328	    if (!title) {
329	      titleInput.classList.add("invalid");
330	      titleErr.textContent = "标题不能为空。";
331	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
332	    }
333	
334	    const cards = [...qBox.querySelectorAll(".q-card")];
335	    if (cards.length === 0) {
336	      qErr.textContent = "问卷至少需要保留一道题。";
337	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
338	    }
339	
340	    const payloadQuestions = [];
341	    cards.forEach((card, i) => {
342	      const loc = `第 ${i + 1} 题`;
343	      const titleEl = card.querySelector(".q-title");
344	      const qTitle = titleEl.value.trim();
345	      if (!qTitle) {
346	        titleEl.classList.add("invalid");
347	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
348	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
349	      }
350	      const q = {
351	        type: card.dataset.type,
352	        title: qTitle,
353	        required: card.querySelector(".q-required").checked
354	      };
355	      if (card.dataset.type === "single_choice") {
356	        const optInputs = [...card.querySelectorAll(".opt-text")];
357	        const values = optInputs.map(el => el.value.trim());
358	        const optErr = card.querySelector(".opt-err");
359	        const seen = new Set();
360	        values.forEach((val, j) => {
361	          if (!val) {
362	            optInputs[j].classList.add("invalid");
363	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
364	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
365	          } else if (seen.has(val)) {
366	            optInputs[j].classList.add("invalid");
367	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
368	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
369	          }
370	          seen.add(val);
371	        });
372	        if (values.length < 2) {
373	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
374	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
375	        }
376	        q.options = values;
377	      }
378	      payloadQuestions.push(q);
379	    });
380	
381	    if (problems.length) {
382	      showBanner(problems);
383	      return;
384	    }
385	
386	    const payload = {title, description: descArea.value, questions: payloadQuestions};
387	    // 点击保存这一刻的整份表单快照：这次请求只代表这份内容。成功返回后拿它与
388	    // 当前表单比较——等待期间的任何输入/增删都不属于本次保存。
389	    const submittedState = {
390	      title,
391	      description: descArea.value,
392	      questions: payloadQuestions.map(q => ({
393	        type: q.type, title: q.title, required: q.required, options: q.options || []
394	      }))
395	    };
396	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
397	    // 这次保存只属于发起它的那一代表单；响应再晚返回，只要用户已经离开
398	    // （首页/详情/编辑切换、重新进入同一问卷、浏览器前进后退），其成功或
399	    // 失败结果都必须静默丢弃，不能跳转、清空或提示到当前页面上。
400	    const submitView = view;
401	    let resp;
402	    try {
403	      resp = await fetch(endpoint, {
404	        method: mode === "edit" ? "PUT" : "POST",
405	        headers: {"Content-Type": "application/json"},
406	        body: JSON.stringify(payload)
407	      });
408	    } catch (err) {
409	      if (submitView !== activeView) return;
410	      // 请求未成功：保留当前全部输入与增删结果
411	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
412	      return;
413	    }
414	    if (submitView !== activeView) return;
415	    let data = {};
416	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
417	    if (submitView !== activeView) return;
418	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
419	    if (saved && data.id !== undefined) {
420	      if (mode === "create") {
421	        form.reset();
422	        qBox.replaceChildren();
423	        autoGrow(titleInput);
424	        if (hooks && hooks.onCreated) hooks.onCreated();
425	        location.hash = `#/surveys/${data.id}`;
426	        return;
427	      }
428	      // 编辑模式：先把“这次提交的内容”记为已保存（服务器上的草稿正是它）。
429	      if (hooks && hooks.markSaved) hooks.markSaved(submittedState);
430	      // 比较点击保存前后的整份表单：等待期间改过又恢复原值时结构相同，按
431	      // 无新改动处理，仍进入详情。
432	      const stillSame = hooks && hooks.isCurrent ? hooks.isCurrent(submittedState) : true;
433	      if (stillSame) {
434	        location.hash = `#/surveys/${data.id}`;
435	        return;
436	      }
437	      // 等待期间出现了新的修改：留在编辑页，保留当前完整内容与顺序。绿色块
438	      // 只确认“刚才提交的内容已保存”，黄色块提示“当前还有未保存的修改”，
439	      // 不自动补交，也不撤销已成功的保存。
440	      renderSaveStatus(true);
441	      return;
442	    }
443	    // 服务端未确认保存成功：不清空任何输入，展示具体问题
444	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
445	  }
446	
447	  return form;
448	}
