620	def validate_survey(obj):
621	    """Validate a decoded survey payload.
622	
623	    Returns (clean_survey, None) on success or (None, error_message) on failure.
624	    Strings are stored trimmed of surrounding whitespace; description keeps its
625	    raw value so Chinese, quotes and newlines are preserved.
626	    """
627	    if not isinstance(obj, dict):
628	        return None, "请求体必须是 JSON 对象"
629	    if "title" not in obj:
630	        return None, "缺少字段 title"
631	    title = obj["title"]
632	    if not isinstance(title, str):
633	        return None, "title 必须是字符串"
634	    title = title.strip()
635	    if not title:
636	        return None, "title 不能为空（或全为空白字符）"
637	
638	    description = obj.get("description", "")
639	    if not isinstance(description, str):
640	        return None, "description 必须是字符串"
641	
642	    if "questions" not in obj:
643	        return None, "缺少字段 questions"
644	    raw_questions = obj["questions"]
645	    if not isinstance(raw_questions, list):
646	        return None, "questions 必须是数组"
647	    if len(raw_questions) == 0:
648	        return None, "questions 至少需要一道题"
649	
650	    questions = []
651	    for index, raw_question in enumerate(raw_questions, start=1):
652	        location = f"第 {index} 题"
653	        if not isinstance(raw_question, dict):
654	            return None, f"{location}（questions[{index - 1}]）必须是对象"
655	
656	        if "type" not in raw_question:
657	            return None, f"{location}：缺少字段 type"
658	        question_type = raw_question["type"]
659	        if not isinstance(question_type, str):
660	            return None, f"{location}：type 必须是字符串"
661	        if question_type not in QUESTION_TYPES:
662	            shown = json.dumps(question_type, ensure_ascii=False)
663	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
664	
665	        if "title" not in raw_question:
666	            return None, f"{location}：缺少字段 title"
667	        question_title = raw_question["title"]
668	        if not isinstance(question_title, str):
669	            return None, f"{location}：title 必须是字符串"
670	        question_title = question_title.strip()
671	        if not question_title:
672	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
673	
674	        required = raw_question.get("required", False)
675	        if not isinstance(required, bool):
676	            return None, f"{location}：required 必须是布尔值"
677	
678	        raw_options = raw_question.get("options", [])
679	        if not isinstance(raw_options, list):
680	            return None, f"{location}：options 必须是数组"
681	
682	        options = []
683	        if question_type == "text":
684	            if len(raw_options) > 0:
685	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
686	        else:
687	            if len(raw_options) < 2:
688	                return None, f"{location}：单选题至少需要两个选项"
689	            seen = set()
690	            for option_index, raw_option in enumerate(raw_options, start=1):
691	                if not isinstance(raw_option, str):
692	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
693	                option = raw_option.strip()
694	                if not option:
695	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
696	                if option in seen:
697	                    shown = json.dumps(option, ensure_ascii=False)
698	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
699	                seen.add(option)
700	                options.append(option)
701	
702	        questions.append({
703	            "type": question_type,
704	            "title": question_title,
705	            "required": required,
706	            "options": options,
707	        })
708	
709	    return {
710	        "title": title,
711	        "description": description,
712	        "questions": questions,
713	    }, None
