716	def main():
717	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
718	    commands = parser.add_subparsers(dest="command", required=True)
719	    serve = commands.add_parser("serve", help="Start the HTTP service")
720	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
721	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
722	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
723	    args = parser.parse_args()
724	    if not 0 <= args.port <= 65535:
725	        parser.error("port must be between 0 and 65535")
726	    args.data_dir.mkdir(parents=True, exist_ok=True)
727	    # 每个连接由独立线程处理（见下方 ThreadingHTTPServer），因此数据库连接
728	    # 会被多个线程共享：check_same_thread=False 允许跨线程使用，所有读写再
729	    # 经 db_lock 串行化，保证一次保存/替换内部的多条语句仍然原子生效。
730	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite", check_same_thread=False)
731	    db_lock = threading.Lock()
732	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
733	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
734	    if "description" not in columns:
735	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
736	    database.execute(
737	        "CREATE TABLE IF NOT EXISTS questions ("
738	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
739	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
740	    )
741	    database.execute(
742	        "CREATE TABLE IF NOT EXISTS question_options ("
743	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
744	    )
745	    database.commit()
746	
747	    def survey_detail(survey_id):
748	        with db_lock:
749	            row = database.execute(
750	                "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
751	                (survey_id,),
752	            ).fetchone()
753	            if row is None:
754	                return None
755	            title, description = row
756	            questions = []
757	            question_rows = database.execute(
758	                "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
759	                (survey_id,),
760	            ).fetchall()
761	            for question_id, question_type, question_title, required in question_rows:
762	                options = [option_row[0] for option_row in database.execute(
763	                    "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
764	                    (question_id,),
765	                )]
766	                questions.append({
767	                    "type": question_type,
768	                    "title": question_title,
769	                    "required": bool(required),
770	                    "options": options,
771	                })
772	        return {
773	            "id": survey_id,
774	            "title": title,
775	            "description": description,
776	            "questions": questions,
777	        }
778	
779	    def save_survey(clean):
780	        """Insert the whole survey atomically; returns the new id."""
781	        with db_lock:
782	            try:
783	                cursor = database.execute(
784	                    "INSERT INTO surveys (title, description) VALUES (?, ?)",
785	                    (clean["title"], clean["description"]),
786	                )
787	                survey_id = cursor.lastrowid
788	                write_questions(survey_id, clean["questions"])
789	                database.commit()
790	                return survey_id
791	            except Exception:
792	                database.rollback()
793	                raise
794	
795	    def write_questions(survey_id, questions):
796	        """Replace all questions/options of a survey with the given ordered list."""
797	        old_question_ids = [row[0] for row in database.execute(
798	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
799	        )]
800	        if old_question_ids:
801	            placeholders = ",".join("?" for _ in old_question_ids)
802	            database.execute(
803	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
804	                old_question_ids,
805	            )
806	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
807	        for position, question in enumerate(questions):
808	            question_cursor = database.execute(
809	                "INSERT INTO questions (survey_id, position, type, title, required) "
810	                "VALUES (?, ?, ?, ?, ?)",
811	                (survey_id, position, question["type"], question["title"],
812	                 1 if question["required"] else 0),
813	            )
814	            question_id = question_cursor.lastrowid
815	            for option_position, option in enumerate(question["options"]):
816	                database.execute(
817	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
818	                    (question_id, option_position, option),
819	                )
820	
821	    def replace_survey(survey_id, clean):
822	        """Replace a whole survey atomically; keeps the same id.
823	
824	        Returns False when the survey does not exist (no record is created).
825	        """
826	        with db_lock:
827	            row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
828	            if row is None:
829	                return False
830	            try:
831	                database.execute(
832	                    "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
833	                    (clean["title"], clean["description"], survey_id),
834	                )
835	                write_questions(survey_id, clean["questions"])
836	                database.commit()
837	                return True
838	            except Exception:
839	                database.rollback()
840	                raise
