842	    class Handler(BaseHTTPRequestHandler):
843	        def respond(self, status, value, *, html=False, allow=None):
844	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
845	            self.send_response(status)
846	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
847	            self.send_header("Content-Length", str(len(payload)))
848	            if status == 405 and allow is not None:
849	                self.send_header("Allow", ", ".join(allow))
850	            self.end_headers()
851	            self.wfile.write(payload)
852	
853	        def list_surveys(self):
854	            with db_lock:
855	                records = [
856	                    {"id": row[0], "title": row[1]}
857	                    for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
858	                ]
859	            self.respond(200, {RESOURCE: records})
860	
861	        def read_payload(self):
862	            """Read and decode a JSON request body.
863	
864	            Returns (payload, None) or (None, error_message).
865	            """
866	            try:
867	                length = int(self.headers.get("Content-Length") or 0)
868	            except ValueError:
869	                length = -1
870	            if length < 0:
871	                return None, "Content-Length 无效"
872	            if length > MAX_BODY_BYTES:
873	                return None, "请求体过大"
874	            body = self.rfile.read(length) if length else b""
875	            try:
876	                return json.loads(body.decode("utf8")), None
877	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
878	                return None, f"请求体不是合法 JSON：{error}"
879	
880	        def create_survey(self):
881	            payload, error = self.read_payload()
882	            if error is not None:
883	                self.respond(400, {"error": error})
884	                return
885	
886	            clean, error = validate_survey(payload)
887	            if error is not None:
888	                self.respond(400, {"error": error})
889	                return
890	            try:
891	                survey_id = save_survey(clean)
892	            except sqlite3.DatabaseError as error:
893	                self.respond(500, {"error": f"保存失败：{error}"})
894	                return
895	            result = {"id": survey_id, **clean}
896	            self.respond(201, result)
897	
898	        def update_survey(self, survey_id):
899	            payload, read_error = self.read_payload()
900	            if survey_detail(survey_id) is None:
901	                # Editing a missing id is always 404 and must never create one.
902	                self.respond(404, {"error": "not found"})
903	                return
904	            if read_error is not None:
905	                self.respond(400, {"error": read_error})
906	                return
907	
908	            # Full replacement: validate before touching the stored draft so a
909	            # rejected request leaves the old survey exactly as it was.
910	            clean, error = validate_survey(payload)
911	            if error is not None:
912	                self.respond(400, {"error": error})
913	                return
914	            try:
915	                replace_survey(survey_id, clean)
916	            except sqlite3.DatabaseError as error:
917	                self.respond(500, {"error": f"保存失败：{error}"})
918	                return
919	            self.respond(200, {"id": survey_id, **clean})
920	
921	        def route(self):
922	            location = urlsplit(self.path).path
923	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
924	
925	            if location == "/api/surveys":
926	                allowed = ["GET", "POST"]
927	            elif location in ("/", "/health"):
928	                allowed = ["GET"]
929	            elif detail_match:
930	                allowed = ["GET", "PUT"]
931	            else:
932	                self.respond(404, {"error": "not found"})
933	                return
934	
935	            if self.command not in allowed:
936	                self.respond(405, {"error": "method not allowed"}, allow=allowed)
937	                return
938	
939	            if location == "/":
940	                self.respond(200, PAGE, html=True)
941	            elif location == "/health":
942	                self.respond(200, {"status": "ok", "product": PRODUCT})
943	            elif location == "/api/surveys":
