        # 再观察一拍，确认没有延迟的跳转/改写。
        self.page.settle(0.4)
        self.assertEqual(self.page.eval("location.hash"), "#/")
        self.assert_form_state(self.page.snapshot(), expected, "旧保存成功后再次观察")

        # 旁证：合法保存确实已在服务器完成，不需要因离开而撤销。
