# 夹具的 wait_held_put 返回 held[0] 且不弹出；这里按基线长度等待“新”挂起
# 的请求并返回最新一个，避免取到上一笔已放行的旧请求。
def _wait_new_put(self, baseline, timeout=8):
    end = time.time() + timeout
    while time.time() < end:
        with self.page._held_cond:
            if len(self.page.held) > baseline:
                return self.page.held[-1]
        time.sleep(0.1)
    raise AssertionError("没有出现新的保存请求（PUT）")

